from __future__ import annotations

"""Correlation tuple builders for QRadar-style offense bucketing (starter favors NAT + rule)."""

from qradar_models import SecurityEvent


def nat_rule_correlation_key(event: SecurityEvent) -> tuple[str, str]:
    """Groups all activity on the same egress IP + rule (problematic behind shared NAT)."""
    return (event.source_ip, event.rule_id)


def user_rule_correlation_key(event: SecurityEvent) -> tuple[str, str]:
    """SOC-friendly boundary: same interactive identity + detection rule."""
    return (event.username.strip().lower(), event.rule_id)


def offense_slug_from_key(username: str, rule_id: str) -> str:
    return f"offense-{username}-{rule_id}".lower()


def describe_correlation_strategy(key_kind: str) -> str:
    return f"dedupe_strategy={key_kind}"


def shared_address_hint(source_ip: str) -> str:
    return f"egress::{source_ip}"


def merge_username_domains(left: str, right: str) -> tuple[bool, str]:
    if left.strip().lower() == right.strip().lower():
        return True, left
    return False, f"{left}|{right}"


def stable_tuple_for_sort(key: tuple[str, str]) -> tuple[str, str]:
    return (key[0].lower(), key[1].lower())


def event_fingerprint(event: SecurityEvent) -> str:
    return "|".join((event.event_id, event.username, event.rule_id, event.source_ip))


def rule_family_token(rule_id: str) -> str:
    head = rule_id.strip().split("-")[0] if rule_id.strip() else "unknown"
    return head.lower()


def severity_bucket(severity: int) -> str:
    if severity <= 3:
        return "low"
    if severity <= 6:
        return "medium"
    return "high"


def correlation_key_label(key: tuple[str, str]) -> str:
    return f"{key[0]}::{key[1]}"


def analyst_queue_subject(event: SecurityEvent) -> str:
    return f"{event.username}@{event.rule_id}"


def offense_merge_eligibility_note(same_user: bool, same_rule: bool, same_ip: bool) -> str:
    if same_user and same_rule:
        return "eligible_single_offense"
    if same_ip and same_rule and not same_user:
        return "shared_nat_split_required"
    return "independent_signals"


def correlation_tuple_signature(key: tuple[str, str]) -> str:
    left, right = key
    return f"{hash(left + right) & 0xFFFF:04x}"


def empty_correlation_placeholder() -> tuple[str, str]:
    return ("", "")


def ip_rule_pair_label(ip: str, rule_id: str) -> str:
    return f"{ip}#{rule_id}"

