from __future__ import annotations

"""Materialize QRadar-style offenses from normalized security events."""

from correlation_keys import nat_rule_correlation_key, offense_slug_from_key
from qradar_models import OffenseRecord, SecurityEvent


def _offense_key(event: SecurityEvent) -> tuple[str, str]:
    # Participant: switch to username + rule correlation (see correlation_keys.user_rule_correlation_key).
    return nat_rule_correlation_key(event)


def _offense_id(event: SecurityEvent) -> str:
    return offense_slug_from_key(event.username, event.rule_id)


def _new_offense(event: SecurityEvent) -> OffenseRecord:
    return OffenseRecord(
        offense_id=_offense_id(event),
        username=event.username,
        rule_id=event.rule_id,
        source_ips=(event.source_ip,),
        event_ids=(event.event_id,),
        event_count=1,
        max_severity=event.severity,
        first_observed_minute=event.observed_minute,
        last_observed_minute=event.observed_minute,
    )


def _append_event(offense: OffenseRecord, event: SecurityEvent) -> OffenseRecord:
    source_ips = offense.source_ips
    if event.source_ip not in source_ips:
        source_ips = (*source_ips, event.source_ip)
    return OffenseRecord(
        offense_id=offense.offense_id,
        username=offense.username,
        rule_id=offense.rule_id,
        source_ips=source_ips,
        event_ids=(*offense.event_ids, event.event_id),
        event_count=offense.event_count + 1,
        max_severity=max(offense.max_severity, event.severity),
        first_observed_minute=min(offense.first_observed_minute, event.observed_minute),
        last_observed_minute=max(offense.last_observed_minute, event.observed_minute),
    )


def _as_dict(offense: OffenseRecord) -> dict[str, object]:
    return {
        "offense_id": offense.offense_id,
        "username": offense.username,
        "rule_id": offense.rule_id,
        "source_ips": list(offense.source_ips),
        "event_ids": list(offense.event_ids),
        "event_count": offense.event_count,
        "max_severity": offense.max_severity,
        "first_observed_minute": offense.first_observed_minute,
        "last_observed_minute": offense.last_observed_minute,
    }


OFFENSE_PAYLOAD_FIELDS = (
    "offense_id",
    "username",
    "rule_id",
    "source_ips",
    "event_ids",
    "event_count",
    "max_severity",
    "first_observed_minute",
    "last_observed_minute",
)


def offense_payload_field_count() -> int:
    return len(OFFENSE_PAYLOAD_FIELDS)


def build_qradar_offenses(events: list[SecurityEvent]) -> dict[str, object]:
    offenses_by_key: dict[tuple[str, str], OffenseRecord] = {}
    seen_event_ids: set[str] = set()
    skipped_events: list[dict[str, object]] = []

    for event in events:
        if event.event_id in seen_event_ids:
            skipped_events.append(
                {
                    "event_id": event.event_id,
                    "reason": "duplicate_event_id",
                    "username": event.username,
                    "rule_id": event.rule_id,
                }
            )
            continue
        seen_event_ids.add(event.event_id)

        key = _offense_key(event)
        existing = offenses_by_key.get(key)
        if existing is None:
            offenses_by_key[key] = _new_offense(event)
        else:
            offenses_by_key[key] = _append_event(existing, event)

    offenses = [_as_dict(offense) for offense in offenses_by_key.values()]
    return summarize_offenses(offenses, skipped_events)


def summarize_offenses(
    offenses: list[dict[str, object]],
    skipped_events: list[dict[str, object]],
) -> dict[str, object]:
    return {
        "offense_count": len(offenses),
        "event_count": sum(int(offense["event_count"]) for offense in offenses),
        "skipped_event_count": len(skipped_events),
        "offenses": offenses,
        "skipped_events": skipped_events,
    }


class QradarOffenseBuilder:
    """Stateless builder matching the QRadar intake preview hook used in CI."""

    def build(self, events: list[SecurityEvent]) -> dict[str, object]:
        return build_qradar_offenses(events)

