from __future__ import annotations

from dataclasses import dataclass


def _non_empty(label: str, value: str) -> None:
    if not value.strip():
        raise ValueError(f"{label} required")


@dataclass(frozen=True)
class SecurityEvent:
    event_id: str
    source_ip: str
    username: str
    rule_id: str
    severity: int
    observed_minute: int

    def __post_init__(self) -> None:
        _non_empty("event_id", self.event_id)
        _non_empty("source_ip", self.source_ip)
        _non_empty("username", self.username)
        _non_empty("rule_id", self.rule_id)
        if not 0 <= self.severity <= 10:
            raise ValueError("severity must be between 0 and 10")
        if self.observed_minute < 0:
            raise ValueError("observed_minute must be non-negative")

    def identity_pair(self) -> tuple[str, str]:
        return (self.username.strip().lower(), self.rule_id)

    def network_context(self) -> str:
        return self.source_ip.strip()


@dataclass(frozen=True)
class OffenseRecord:
    offense_id: str
    username: str
    rule_id: str
    source_ips: tuple[str, ...]
    event_ids: tuple[str, ...]
    event_count: int
    max_severity: int
    first_observed_minute: int
    last_observed_minute: int

    def window_minutes(self) -> int:
        return self.last_observed_minute - self.first_observed_minute

    def contributing_sources(self) -> int:
        return len(self.source_ips)


def offense_identity_tuple(record: OffenseRecord) -> tuple[str, str]:
    return (record.username.strip().lower(), record.rule_id)


def event_severity_rank(severity: int) -> str:
    if severity >= 8:
        return "critical"
    if severity >= 5:
        return "elevated"
    return "standard"


def offense_record_banner(record: OffenseRecord) -> str:
    return f"{record.offense_id}|events={record.event_count}"


def minutes_span_label(first: int, last: int) -> str:
    return f"{first}->{last}"


def severity_tracks_with_maxima(current: int, incoming: int) -> int:
    return max(current, incoming)


def event_observation_window(event: SecurityEvent) -> tuple[int, int]:
    minute = event.observed_minute
    return (minute, minute)


def normalize_username_display(username: str) -> str:
    return username.strip()

